{
  "technical_and_design_decisions": [
    "Use Spring Boot 1.1.x spring-boot-starter-security and its auto-configuration to provide Basic Auth for the spring-xd-dirt admin server; no custom security framework will be written.",
    "Control Basic Auth via the Spring Boot property server.basic.enabled, with the default set to false in application.yml so out-of-the-box behavior is unchanged.",
    "Externalize single-user credentials through Spring Boot's security.user.* properties (name, password, role), exposed and overridable via the existing servers.yml configuration mechanism.",
    "Implement XD Shell support by adding --username and --password options to the 'admin config server' command, storing credentials in the shell's connection state, and injecting the Basic Authorization header into all admin REST calls via a RestTemplate ClientHttpRequestInterceptor.",
    "Manage Spring Boot snapshot and RELEASE upgrades through the Gradle build (gradle.properties/build.gradle version changes), relying on the existing automated test suite to detect regressions.",
    "Treat U6 strictly as a spike: deliver documented options, team feedback, phased plan, and follow-up stories only; no production code for the module archive upload REST API.",
    "Build Docker images on an Ubuntu base with Java 7.x; the sandbox image runs Redis, RabbitMQ, and the full XD singlenode jar inside one container managed by a startup script/supervisord, while the production-ready image runs only the XD process and expects external middleware."
  ],
  "assumptions": [
    "The existing Spring XD codebase is available with its Gradle build, including the spring-xd-dirt and spring-xd-shell modules and existing admin REST endpoints to be secured.",
    "One developer performs all work; estimates are in ideal workdays of 8 hours, excluding meetings and calendar overhead.",
    "servers.yml is already a supported XD configuration file; the work is to wire security properties into it, not to create the file mechanism.",
    "A working Docker host/daemon and CI infrastructure are available for building and testing images; base Ubuntu and Java 7 images/packages are obtainable.",
    "The specification's Java 7.x requirement for the Docker images is followed as written, despite newer Spring versions requiring newer Java.",
    "U5 (Spring Boot RELEASE) builds on U4 (snapshot already integrated), so it is only a version switch plus verification.",
    "Security applies to the admin server REST endpoints only; no UI, LDAP, or multi-user/role management is in scope.",
    "Unit/integration test work and self code-review effort are included within each activity estimate; no separate QA team is involved.",
    "Existing automated build and test suite can be run locally and in CI to validate dependency upgrades and security behavior."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Upgrade to latest Spring Boot snapshot (U4)",
      "activity_description": "Update Gradle build to pull the latest Spring Boot 1.1.x snapshot, resolve any compilation or API/behavior changes in spring-xd-dirt and related modules, and run the full build and test suite to confirm stability.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A2",
      "activity_name": "Switch to Spring Boot RELEASE dependency (U5)",
      "activity_description": "Replace the snapshot version with the Spring Boot RELEASE version, verify dependency resolution, and re-run the build and automated tests to confirm no regressions.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A3",
      "activity_name": "Add Basic Auth starter dependency and default configuration (U1)",
      "activity_description": "Add spring-boot-starter-security to the spring-xd-dirt build, add server.basic.enabled=false default to application.yml, and verify that enabling the property activates Basic Auth challenge on the admin server.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A4",
      "activity_name": "Test Basic Auth enable/disable behavior (U1)",
      "activity_description": "Manually and via integration tests verify that admin REST endpoints return 401/auth challenge when server.basic.enabled=true and behave as before when false, including valid and invalid credential cases.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A5",
      "activity_name": "Implement single-user security configuration via servers.yml (U2)",
      "activity_description": "Wire Spring Boot security.user.* properties (name, password, role) into XD's servers.yml-based configuration so a single user's credentials can be provided and overridden as needed; provide sensible defaults and property resolution.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A6",
      "activity_name": "Test and document servers.yml security overrides (U2)",
      "activity_description": "Verify override precedence (defaults vs servers.yml), test customized credentials against a secured admin server, and document the supported properties.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A7",
      "activity_name": "Add --username/--password options to shell admin config command (U3)",
      "activity_description": "Extend the XD Shell 'admin config server' command with --username and --password options, validate input, and persist the credentials in the shell's admin connection state/configuration.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A8",
      "activity_name": "Propagate Basic Auth credentials from shell REST client (U3)",
      "activity_description": "Implement Basic Authorization header injection (e.g., RestTemplate ClientHttpRequestInterceptor) so all shell-to-admin REST requests use the configured credentials when targeting a secured server.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A9",
      "activity_name": "Integration test shell against secured admin server (U3)",
      "activity_description": "Test end-to-end shell interaction with an admin server secured by Basic Auth: connect with correct/incorrect credentials, verify commands work when authorized and fail cleanly when not.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A10",
      "activity_name": "Spike: assess and document module archive upload REST API options (U6)",
      "activity_description": "Assess the customer requirement, brainstorm design options for a REST API to upload archives containing custom module definitions and configurations, and document the options with pros/cons.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A11",
      "activity_name": "Spike: socialize, phase, and create follow-up stories (U6)",
      "activity_description": "Review the documented options with the team, incorporate feedback, identify implementation phases, and create the follow-up user stories for the chosen approach.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A12",
      "activity_name": "Create sandbox Docker image (U7)",
      "activity_description": "Author Dockerfile and startup scripts for an Ubuntu-based image containing Java 7.x, Redis, RabbitMQ, and the full XD jar, with all services launchable in a single container (e.g., via supervisord or init script).",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A13",
      "activity_name": "Build and validate sandbox Docker image (U7)",
      "activity_description": "Build the sandbox image, run it, and validate end-to-end that Redis, RabbitMQ, and XD singlenode start correctly and that a basic XD flow works for experimentation.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A14",
      "activity_name": "Create production-ready Docker image (U8)",
      "activity_description": "Author a lean Ubuntu-based Dockerfile with Java 7.x and the full XD jar as the single managed process, including entrypoint, environment configuration hooks, and baseline hardening for production use.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A15",
      "activity_name": "Build and validate production-ready Docker image (U8)",
      "activity_description": "Build the production image, run container-level verification (startup, health of XD process, connectivity to external Redis/RabbitMQ), and finalize it as a deployment baseline.",
      "most_likely_effort": 1
    }
  ],
  "reported_total": {
    "most_likely_effort": 24
  }
}

